```

```ts
row.fromFilter(["and", ["name", "contains", "phone"], ["price", ">=", 100]]);
// [{ field: "name", text: "phone" }, { field: "price", text: "100.." }]

row.fromFilter(["or", ["name", "=", "phone"], ["name", "=", "tablet"]]);
// false

```ts
row.toText(["or", ["region", "contains", "123"], ["product", "=", "567"]]);
